const items = $input.all();

// Extract temperature and humidity
const temperature = items.find(i => i.json.temperature)?.json.temperature || 0;
const humidity = items.find(i => i.json.humidity)?.json.humidity || 0;

// Extract AI caption (output from previous node / agent)
const aiCaption = items.find(i => i.json.output)?.json.output || "Weather is great!";

// Build the combined prompt text
const promptText = `In a sleek, futuristic environment with soft ambient lighting, a high-tech digital display showcases a professional weather advertisement. The holographic screen presents real-time conditions: ${temperature}°C and ${humidity}% humidity, displayed with elegant 3D icons of a thermometer and humidity gauge. Subtle motion graphics animate the readings with smooth, dynamic transitions. Beneath the data, bold yet refined typography spells out ${aiCaption} in a luminous modern sans-serif font. The background features a minimalist, glass like futuristic setting glowing softly with gradients of cyan, silver, and white giving the impression of a premium weather technology brand. Holographic effects and light refractions add depth and realism, creating the feel of a next-generation professional weather display poster that exudes clarity, innovation, and sophistication.`;

// Return as a single JSON object
return [{
  json: {
    prompt_text: promptText
  }
}];

// Kunin ang raw string o JSON object galing sa input
const input = $input.first().json;

// Kung ang data ay galing sa "chatInput" field (string), i-parse muna
let parsed = {};
if (typeof input.chatInput === "string") {
  try {
    parsed = JSON.parse(input.chatInput);
  } catch (e) {
    parsed = {};
  }
}
// Kung galing sa body (webhook), gamitin direkta
else if (input.body) {
  parsed = input.body;
}

// Kunin ang temperature at humidity (may fallback)
const temperature = parsed.temperature ?? 0;
const humidity = parsed.humidity ?? 0;

return {
  json: {
    temperature,
    humidity
  }
};

